import * as http from 'node:http';
import * as net from 'node:net';
function wrap(fn: any): any { return fn; }
function main(): void {
  const server = http.createServer(wrap((req: any, res: any): void => {
    req.on('end', (): void => { console.log('end'); });
    res.end('hello');
  }));
  server.listen(0, (): void => {
    const client = net.connect((server.address() as any).port);
    client.on('data', (): void => {});
    client.on('close', (): void => { server.close(); });
    client.end('POST / HTTP/1.1\r\nHost: x\r\nConnection: close\r\nContent-Length: 2\r\n\r\nhi');
  });
}
